package com.robot.platform.ai;
import com.robot.platform.integration.AbstractRobotPlatformIntegrationTest;import com.robot.platform.ai.memory.dal.dataobject.AiMemoryDO;import com.robot.platform.ai.memory.dal.mysql.AiMemoryMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import java.math.BigDecimal;import java.time.LocalDateTime;import static org.assertj.core.api.Assertions.assertThat;
class AiTenantIsolationIntegrationTest extends AbstractRobotPlatformIntegrationTest{@Autowired AiMemoryMapper mapper;@Test void tenantACannotDiscoverTenantBMemoryById(){AiMemoryDO m=new AiMemoryDO();m.setTenantId(202L);m.setScope("ROBOT");m.setRobotId(9L);m.setMemoryType("FACT");m.setContent("tenant-b");m.setImportance(new BigDecimal(".8"));m.setConfidence(new BigDecimal(".9"));m.setFirstObservedAt(LocalDateTime.now());m.setLastObservedAt(LocalDateTime.now());m.setStatus("ACTIVE");m.setCreatedAt(LocalDateTime.now());m.setUpdatedAt(LocalDateTime.now());mapper.insert(m);assertThat(mapper.selectByIdAndTenantId(m.getId(),101L)).isNull();assertThat(mapper.selectByIdAndTenantId(m.getId(),202L)).isNotNull();mapper.deleteById(m.getId());}}
